items.referenceSolution:
#include <stdio.h>
#include <stdarg.h>

int biggest(int count, ...) {
    va_list list;
    va_start(list, count);
    int best = va_arg(list, int);
    for (int i = 1; i < count; i++) {
        int v = va_arg(list, int);
        if (v > best) {
            best = v;
        }
    }
    va_end(list);
    return best;
}

int main(void) {
    printf("%d\n", biggest(4, 3, 9, 2, 7));
    return 0;
}

